@Transactional
public void createOrder(
        CreateOrderRequest request
) {
    Order order =
        orderRepository.save(
            Order.from(request)
        );

    inventoryService.reserve(
        request.productId(),
        request.quantity()
    );

    paymentRepository.save(
        Payment.pending(
            order.getId()
        )
    );
}
